export class Booking {
  readonly lab: string;
  constructor(lab: string) { this.lab = lab; }
  rename(next: string): void {
    // lab is readonly — it cannot be reassigned.
    this.lab = next;
  }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Booking } from '../src/booking.ts';
test('lab is fixed at construction', () => { assert.equal(new Booking('BE-201').lab, 'BE-201'); });

