export class Pricing {
  protected rate = 10;
}
export class LabPricing extends Pricing {
  quote(hours: number): number { return hours * this.rate; }
}
// rate is protected — it cannot be read from outside the class hierarchy.
export function peek(p: Pricing): number { return p.rate; }

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { LabPricing, peek } from '../src/price.ts';
test('peek returns a subclass quote', () => { assert.equal(peek(new LabPricing()), 10); });

